SymbolAttribute.Value:
{%- if Variant == 'Signal 75E-1 Kjedebrudd' -%}
	Km.{{ FRA_1 | round | divided_by:1000 | floor }}
{%- else -%}
	Pr.{{ FRA_1 | times:1000 | round | divided_by:1000000 | floor }},
{%- endif %}

{%- if Variant == 'Signal 75E-1 Kjedebrudd' -%}
	{{ assign tmp = FRA_2 | round | modulo:1000 }}{%- if tmp < 10 -%} %}{{ tmp | prepend:"00"}}{%- elif tmp < 100 -%}{{ tmp | prepend:"0"}}{% else %}{{tmp}}{% end -%}
{%- else -%}
	{{ assign tmp = FRA_2 | times:1000 | round | modulo:1000000 }}
{%- endif %}

{%- if Variant == 'Signal 75E-1 Kjedebrudd' -%}
	Km.{{ TIL_1 | round | divided_by:1000 | floor }}
{%- else -%}
	Pr.{{ TIL_1 | times:1000 | round | divided_by:1000000 | floor }},
{%- endif %}

{%- if Variant == 'Signal 75E-1 Kjedebrudd' -%}
	{{ TIL_2 | round | modulo:1000 }}
{%- else -%}
	{{ TIL_2 | times:1000 | round | modulo:1000000 }}
{%- endif %}

{%- if sprang > 0 %}+{% endif -%}
{%- if Variant == 'Signal 75E-1 Kjedebrudd' -%}
	{{ SPRANG | round }}m
{%- else -%}
	{{ SPRANG | times:1000 | round | divided_by:1000 }}m
{%- endif %}

